fixed = [(0,1),(0,2),(0,5),(0,8),(0,10),(0,11),(0,12),(2,10),(2,11),(2,13),(2,14),(3,7),(4,5),(5,7),(5,13),(6,14),(6,15),(7,14),(8,14),(8,15),(10,11),(12,15),(13,14),(14,15)]
edges = set(tuple(sorted(e)) for e in fixed)
print(len(edges))

def is_independent(s, edges):
    for a,b in itertools.combinations(s,2):
        if (min(a,b), max(a,b)) in edges:
            return False
    return True

